#[doc(hidden)]
#[macro_export]
macro_rules! fl {
        ("args-header") => { ::std::string::String::from("Arguments") };
        ("autogenerated-passphrase") => { ::std::string::String::from("Using an autogenerated passphrase:") };
        ("err-dec-armor-flag") => { ::std::string::String::from("-a/--armor can't be used with -d/--decrypt.") };
        ("err-dec-missing-identities") => { ::std::string::String::from("Missing identities.") };
        ("err-dec-mixed-identity-passphrase") => { ::std::string::String::from("-i/--identity can't be used with passphrase-encrypted files.") };
        ("err-dec-passphrase-flag") => { ::std::string::String::from("-p/--passphrase can't be used with -d/--decrypt.") };
        ("err-dec-recipient-flag") => { ::std::string::String::from("-r/--recipient can't be used with -d/--decrypt.") };
        ("err-dec-recipients-file-flag") => { ::std::string::String::from("-R/--recipients-file can't be used with -d/--decrypt.") };
        ("err-detected-powershell-corruption") => { ::std::string::String::from("It looks like this file was corrupted by PowerShell redirection.") };
        ("err-enc-broken-file", $($args:tt)*) => {
            ::std::format!("Could not write to file: {err}", $($args)*)
        };
        ("err-enc-broken-stdout", $($args:tt)*) => {
            ::std::format!("Could not write to stdout: {err}", $($args)*)
        };
        ("err-enc-mixed-identity-passphrase") => { ::std::string::String::from("-i/--identity can't be used with -p/--passphrase.") };
        ("err-enc-mixed-recipient-passphrase") => { ::std::string::String::from("-r/--recipient can't be used with -p/--passphrase.") };
        ("err-enc-mixed-recipients-file-passphrase") => { ::std::string::String::from("-R/--recipients-file can't be used with -p/--passphrase.") };
        ("err-enc-plugin-name-flag") => { ::std::string::String::from("-j can't be used with -e/--encrypt.") };
        ("err-failed-to-open-input", $($args:tt)*) => {
            ::std::format!("Failed to open input: {err}", $($args)*)
        };
        ("err-failed-to-open-output", $($args:tt)*) => {
            ::std::format!("Failed to open output: {err}", $($args)*)
        };
        ("err-failed-to-read-input", $($args:tt)*) => {
            ::std::format!("Failed to read from input: {err}", $($args)*)
        };
        ("err-failed-to-write-output", $($args:tt)*) => {
            ::std::format!("Failed to write to output: {err}", $($args)*)
        };
        ("err-identity-ambiguous") => { ::std::string::String::from("-i/--identity requires either -e/--encrypt or -d/--decrypt.") };
        ("err-mixed-encrypt-decrypt") => { ::std::string::String::from("-e/--encrypt can't be used with -d/--decrypt.") };
        ("err-mixed-identity-and-plugin-name") => { ::std::string::String::from("-i/--identity can't be used with -j.") };
        ("err-passphrase-timed-out") => { ::std::string::String::from("Timed out waiting for passphrase input.") };
        ("err-same-input-and-output", $($args:tt)*) => {
            ::std::format!("Input and output are the same file '{filename}'.", $($args)*)
        };
        ("err-ux-A") => { ::std::string::String::from("Did rage not do what you expected? Could an error be more useful?") };
        ("err-ux-B") => { ::std::string::String::from("Tell us") };
        ("err-ux-C") => { ::std::string::String::from("                          ") };
        ("flags-header") => { ::std::string::String::from("Options") };
        ("help-arg-input") => { ::std::string::String::from("Path to a file to read from.") };
        ("help-flag-armor") => { ::std::string::String::from("Encrypt to a PEM encoded format.") };
        ("help-flag-decrypt") => { ::std::string::String::from("Decrypt the input.") };
        ("help-flag-encrypt") => { ::std::string::String::from("Encrypt the input (the default).") };
        ("help-flag-help") => { ::std::string::String::from("Print this help message and exit.") };
        ("help-flag-identity") => { ::std::string::String::from("Use the identity file at IDENTITY. May be repeated.") };
        ("help-flag-max-work-factor") => { ::std::string::String::from("Maximum work factor to allow for passphrase decryption.") };
        ("help-flag-output") => { ::std::string::String::from("Write the result to the file at path OUTPUT.") };
        ("help-flag-passphrase") => { ::std::string::String::from("Encrypt with a passphrase instead of recipients.") };
        ("help-flag-plugin-name") => { ::std::string::String::from("Use age-plugin-PLUGIN-NAME in its default mode as an identity.") };
        ("help-flag-recipient") => { ::std::string::String::from("Encrypt to the specified RECIPIENT. May be repeated.") };
        ("help-flag-recipients-file") => { ::std::string::String::from("Encrypt to the recipients listed at PATH. May be repeated.") };
        ("help-flag-version") => { ::std::string::String::from("Print version info and exit.") };
        ("identity") => { ::std::string::String::from("IDENTITY") };
        ("identity-file-created") => { ::std::string::String::from("created") };
        ("identity-file-pubkey") => { ::std::string::String::from("public key") };
        ("info-decrypting", $($args:tt)*) => {
            ::std::format!("Decrypting {filename}", $($args)*)
        };
        ("input") => { ::std::string::String::from("INPUT") };
        ("keygen-help-flag-convert") => { ::std::string::String::from("Convert an identity file to a recipients file.") };
        ("keygen-help-flag-output") => { ::std::string::String::from("Write the result to the file at path OUTPUT. Defaults to standard output.") };
        ("man-examples-heading") => { ::std::string::String::from("EXAMPLES") };
        ("man-keygen-about") => { ::std::string::String::from("Generate age-compatible encryption key pairs") };
        ("man-keygen-description") => { ::std::string::String::from("rage-keygen generates a new native age key pair, and outputs the identity to\nstandard output or to the OUTPUT file. The output includes the public key and\nthe current time as comments.\n\nIf the output is not going to a terminal, rage-keygen prints the public key to\nstandard error.") };
        ("man-keygen-example-convert") => { ::std::string::String::from("Convert an identity to a recipient") };
        ("man-keygen-example-file", $($args:tt)*) => {
            ::std::format!("Write a new identity to \"{filename}\"", $($args)*)
        };
        ("man-keygen-example-stdout") => { ::std::string::String::from("Generate a new identity") };
        ("man-keygen-flag-convert") => { ::std::string::String::from("Read an identity file from INPUT or from standard input and output the\ncorresponding recipient(s), one per line, with no comments.") };
        ("man-keygen-flag-output") => { ::std::string::String::from("Write the identity to OUTPUT instead of standard output.\n\nIf OUTPUT already exists, it is not overwritten.") };
        ("man-rage-about") => { ::std::string::String::from("A simple, secure, and modern encryption tool") };
        ("man-rage-description") => { ::std::string::String::from("rage encrypts or decrypts INPUT to OUTPUT. The INPUT argument is\noptional and defaults to standard input. Only a single INPUT file may be\nspecified. If -o/--output is not specified, OUTPUT defaults to standard\noutput.\n\nIf -p/--passphrase is specified, the file is encrypted with a passphrase\nrequested interactively. Otherwise, it's encrypted to one or more\nRECIPIENTS specified with -r/--recipient or\n-R/--recipients-file. Every recipient can decrypt the file.\n\nIn -d/--decrypt mode, passphrase-encrypted files are detected automatically\nand the passphrase is requested interactively. Otherwise, one or more\nIDENTITIES specified with -i/--identity are used to decrypt the file.\n\nage encrypted files are binary and not malleable, with around 200 bytes of\noverhead per recipient, plus 16 bytes every 64KiB of plaintext.") };
        ("man-rage-example-enc-github") => { ::std::string::String::from("Encrypt to the SSH keys of a GitHub user") };
        ("man-rage-example-enc-list") => { ::std::string::String::from("Encrypt to a list of recipients") };
        ("man-rage-example-enc-multiple", $($args:tt)*) => {
            ::std::format!("Encrypt {input} to multiple recipients and output to {output}", $($args)*)
        };
        ("man-rage-example-identity-passphrase") => { ::std::string::String::from("Encrypt and decrypt with a passphrase-protected identity file") };
        ("man-rage-example-password") => { ::std::string::String::from("Encrypt and decrypt a file using a passphrase") };
        ("man-rage-example-single") => { ::std::string::String::from("Generate a new identity, encrypt data, and decrypt") };
        ("man-rage-example-ssh") => { ::std::string::String::from("Encrypt and decrypt with an SSH public key") };
        ("man-rage-example-yubikey") => { ::std::string::String::from("Encrypt and decrypt with age-plugin-yubikey") };
        ("man-rage-example-yubikey-setup") => { ::std::string::String::from("Run interactive setup, generate identity file and obtain recipient.") };
        ("man-rage-flag-armor") => { ::std::string::String::from("Encrypt to an ASCII-only \"armored\" encoding.\n\nage armor is a strict version of PEM with type \"AGE ENCRYPTED FILE\",\ncanonical \"strict\" Base64, no headers, and no support for leading and\ntrailing extra data.\n\nDecryption transparently detects and decodes ASCII armoring.") };
        ("man-rage-flag-decrypt") => { ::std::string::String::from("Decrypt INPUT to OUTPUT.\n\nIf INPUT is passphrase encrypted, it will be automatically detected\nand the passphrase will be requested interactively. Otherwise, the\nIDENTITIES specified with -i/--identity are used.\n\nASCII armoring is transparently detected and decoded.") };
        ("man-rage-flag-encrypt") => { ::std::string::String::from("Encrypt INPUT to OUTPUT. This is the default.") };
        ("man-rage-flag-identity-decrypt") => { ::std::string::String::from("Decrypt using the IDENTITIES at IDENTITY.\n\nIDENTITY may be one of the following:\n\na. A file listing IDENTITIES one per line. Empty lines and lines starting\nwith \"#\" are ignored as comments.\n\nb. A passphrase encrypted age file, containing IDENTITIES one per\nline like above. The passphrase is requested interactively. Note that\npassphrase-protected identity files are not necessary for most use cases,\nwhere access to the encrypted identity file implies access to the whole\nsystem.\n\nc. An SSH private key file, in PKCS#1, PKCS#8, or OpenSSH format.\nIf the private key is password-protected, the password is requested\ninteractively only if the SSH identity matches the file. See the\nSSH keys section for more information, including\nsupported key types.\n\nd. \"-\", causing one of the options above to be read from standard input.\nIn this case, the INPUT argument must be specified.\n\nThis option can be repeated. Identities are tried in the order in which are\nprovided, and the first one matching one of the file's recipients is used.\nUnused identities are ignored, but it is an error if the INPUT file is\npassphrase-encrypted and -i/--identity is specified.") };
        ("man-rage-flag-output") => { ::std::string::String::from("Write encrypted or decrypted file to OUTPUT instead of standard output.\nIf OUTPUT already exists it will be overwritten.\n\nIf encrypting without -a/--armor, rage will refuse to output binary to a\nTTY. This can be forced by specifying \"-\" as OUTPUT.") };
        ("man-rage-flag-passphrase") => { ::std::string::String::from("Encrypt with a passphrase, requested interactively from the terminal.\nrage will offer to auto-generate a secure passphrase.\n\nThis option can't be used with other recipient flags.") };
        ("man-rage-flag-plugin-decrypt") => { ::std::string::String::from("Decrypt using the data-less plugin PLUGIN-NAME.\n\nThis is equivalent to using -i/--identity with a file that contains a\nsingle plugin IDENTITY that encodes no plugin-specific data.") };
        ("man-rage-flag-recipient") => { ::std::string::String::from("Encrypt to the explicitly specified RECIPIENT. See the\nRECIPIENTS AND IDENTITIES section for possible recipient\nformats.\n\nThis option can be repeated and combined with other recipient flags,\nand the file can be decrypted by all provided recipients independently.") };
        ("man-rage-flag-recipients-file") => { ::std::string::String::from("Encrypt to the RECIPIENTS listed in the file at PATH, one per\nline. Empty lines and lines starting with \"#\" are ignored as comments.\n\nIf PATH is \"-\", the recipients are read from standard\ninput. In this case, the INPUT argument must be specified.\n\nThis option can be repeated and combined with other recipient flags,\nand the file can be decrypted by all provided recipients independently.") };
        ("man-rage-native-x25519-keys", $($args:tt)*) => {
            ::std::format!("Native age key pairs are generated with rage-keygen(1), and provide small\nencodings and strong encryption based on X25519. They are the recommended\nrecipient type for most applications.\n\nA RECIPIENT encoding begins with \"age1\" and looks like the\nfollowing:\n\n    {example_age_recipient}\n\nAn IDENTITY encoding begins with \"AGE-SECRET-KEY-1\" and looks like the\nfollowing:\n\n    {example_age_identity}\n\nAn encrypted file can't be linked to the native recipient it's encrypted to\nwithout access to the corresponding identity.", $($args)*)
        };
        ("man-rage-native-x25519-keys-heading") => { ::std::string::String::from("Native X25519 keys") };
        ("man-rage-plugins") => { ::std::string::String::from("rage can be extended through plugins. A plugin is only loaded if a corresponding\nRECIPIENT or IDENTITY is specified. (Simply decrypting a file encrypted with\na plugin will not cause it to load, for security reasons among others.)\n\nA RECIPIENT for a plugin named \"example\" starts with \"age1example1\", while an\nIDENTITY starts with \"AGE-PLUGIN-EXAMPLE-1\". They both encode arbitrary plugin-specific\ndata, and are generated by the plugin.\n\nWhen either is specified, rage searches for age-plugin-example in the PATH\nand executes it to perform the file header encryption or decryption. The plugin\nmay request input from the user through rage to complete the operation.\n\nPlugins can be freely mixed with other plugins or natively supported keys.\n\nA plugin is not bound to only encrypt or decrypt files meant for or generated by\nthe plugin. For example, a plugin can be used to decrypt files encrypted to a\nnative X25519 RECIPIENT or even with a passphrase. Similarly, a plugin can\nencrypt a file such that it can be decrypted without the use of any plugin.\n\nPlugins for which the IDENTITY/RECIPIENT distinction doesn't make sense\n(such as a symmetric encryption plugin) may generate only an IDENTITY and\ninstruct the user to perform encryption with the -e/--encrypt and\n-i/--identity flags. Plugins for which the concept of separate identities\ndoesn't make sense (such as a password-encryption plugin) may instruct the user\nto use the -j flag.") };
        ("man-rage-plugins-heading") => { ::std::string::String::from("Plugins") };
        ("man-rage-recipients-and-identities") => { ::std::string::String::from("RECIPIENTS are public values, like a public key, that a file can be encrypted\nto. IDENTITIES are private values, like a private key, that allow decrypting\na file encrypted to the corresponding RECIPIENT.") };
        ("man-rage-recipients-and-identities-heading") => { ::std::string::String::from("RECIPIENTS AND IDENTITIES") };
        ("man-rage-ssh-keys", $($args:tt)*) => {
            ::std::format!("As a convenience feature, rage also supports encrypting to RSA or Ed25519\nssh(1) keys. RSA keys must be at least 2048 bits. This feature employs more\ncomplex cryptography, and should only be used when a native key is not available\nfor the recipient. Note that SSH keys might not be protected long-term by the\nrecipient, since they are revokable when used only for authentication.\n\nA RECIPIENT encoding is an SSH public key in \"authorized_keys\" format\n(see the \"AUTHORIZED_KEYS FILE FORMAT\" section of sshd(8)), starting with\n\"ssh-rsa\" or \"ssh-ed25519\", like the following:\n\n    {example_ssh_rsa}\n    {example_ssh_ed25519}\n\nThe comment at the end of the line, if present, is ignored.\n\nIn recipient files passed to -R/--recipients-file, unsupported but valid\nSSH public keys are ignored with a warning, to facilitate using\n\"authorized_keys\" or GitHub \".keys\" files. (See EXAMPLES.)\n\nAn IDENTITY is an SSH private key _file_ passed individually to\n-i/--identity. Note that keys held on hardware tokens such as YubiKeys\nor accessed via ssh-agent(1) are not supported.\n\nAn encrypted file _can_ be linked to the SSH public key it was encrypted to.\nThis is so that rage can identify the correct SSH private key before\nrequesting its password, if any.", $($args)*)
        };
        ("man-rage-ssh-keys-heading") => { ::std::string::String::from("SSH keys") };
        ("man-see-also-heading") => { ::std::string::String::from("SEE ALSO") };
        ("output") => { ::std::string::String::from("OUTPUT") };
        ("plugin-name") => { ::std::string::String::from("PLUGIN-NAME") };
        ("prompt-passphrase") => { ::std::string::String::from("Passphrase") };
        ("rage-after-help-content", $($args:tt)*) => {
            ::std::format!("INPUT defaults to standard input, and OUTPUT defaults to standard output.\nIf OUTPUT exists, it will be overwritten.\n\nRECIPIENT can be:\n- An age public key, as generated by {keygen_name} ({example_age_pubkey}).\n- An SSH public key ({example_ssh_pubkey}).\n\nPATH is a path to a file containing age recipients, one per line\n(ignoring \"#\" prefixed comments and empty lines). \"-\" may be used to\nread recipients from standard input.\n\nIDENTITY is a path to a file with age identities, one per line\n(ignoring \"#\" prefixed comments and empty lines), or to an SSH key file.\nPassphrase-encrypted age identity files can be used as identity files.\nMultiple identities may be provided, and any unused ones will be ignored.\n\"-\" may be used to read identities from standard input.", $($args)*)
        };
        ("rage-after-help-example", $($args:tt)*) => {
            ::std::format!("Example:\n  {example_a}\n  Public key: {example_a_output}\n  {example_b}\n  {example_c}", $($args)*)
        };
        ("rec-dec-armor-flag") => { ::std::string::String::from("Note that armored files are detected automatically.") };
        ("rec-dec-excessive-work", $($args:tt)*) => {
            ::std::format!("To decrypt, retry with --max-work-factor {wf}", $($args)*)
        };
        ("rec-dec-missing-identities") => { ::std::string::String::from("Did you forget to specify -i/--identity?") };
        ("rec-dec-missing-identities-stdin") => { ::std::string::String::from("Did you forget to provide the identity over standard input?") };
        ("rec-dec-passphrase-flag") => { ::std::string::String::from("Note that passphrase-encrypted files are detected automatically.") };
        ("rec-dec-recipient-flag") => { ::std::string::String::from("Did you mean to use -i/--identity to specify a private key?") };
        ("rec-detected-powershell-corruption") => { ::std::string::String::from("Consider using -o/--output or -a/--armor to encrypt files in PowerShell.") };
        ("rec-enc-broken-stdout") => { ::std::string::String::from("Are you piping to a program that isn't reading from stdin?") };
        ("rec-enc-missing-recipients") => { ::std::string::String::from("Did you forget to specify -r/--recipient?") };
        ("recipient") => { ::std::string::String::from("RECIPIENT") };
        ("recipients-file") => { ::std::string::String::from("PATH") };
        ("tty-pubkey") => { ::std::string::String::from("Public key") };
        ("type-passphrase") => { ::std::string::String::from("Type passphrase") };
        ("usage-header") => { ::std::string::String::from("Usage") };
        ("warn-double-encrypting") => { ::std::string::String::from("Encrypting an already-encrypted file") };
        ("warning-msg", $($args:tt)*) => {
            ::std::format!("Warning: {warning}", $($args)*)
        };
}
